-- 216: Remove the footer "Certified Trainers" section (SG footer CMS block, block_id = 1).
--      Drops the heading + its ACTA/ACLP, Autodesk, Quickbooks, Tableau trainer links.
--      Byte-exact REPLACE() with a hex literal -> '' so the surrounding {{store url=''}}
--      markup is untouched and the apply.php splitter is not tripped.

UPDATE cms_block SET content = REPLACE(content, , '') WHERE block_id = 1;
